function moveFly(dt){if(mode!=='fly')return;const d=[-Math.sin(fly.theta),0,-Math.cos(fly.theta)],r=[Math.cos(fly.theta),0,-Math.sin(fly.theta)];let vec=[0,0,0];if(keys.has('KeyW')||keys.has('ArrowUp'))vec=vadd(vec,d);if(keys.has('KeyS')||keys.has('ArrowDown'))vec=vsub(vec,d);if(keys.has('KeyD'))vec=vadd(vec,r);if(keys.has('KeyA'))vec=vsub(vec,r);if(keys.has('KeyE')||keys.has('Space'))vec[1]+=1;if(keys.has('KeyQ')||keys.has('ControlLeft'))vec[1]-=1;let n=Math.hypot(...vec);if(n){let speed=keys.has('ShiftLeft')||keys.has('ShiftRight')?27:10;fly.pos=vadd(fly.pos,vmul(vec,speed*dt/n));}}
