$('share').addEventListener('click',async()=>{let state={theta:+orbit.theta.toFixed(3),phi:+orbit.phi.toFixed(3),dist:+orbit.dist.toFixed(2),target:orbit.target.map(x=>+x.toFixed(1)),y:maxLevel,t:terrainShown,d:deepTerrainShown,f:foliageShown,e:entitiesShown};location.hash='view='+encodeURIComponent(JSON.stringify(state));let link=location.href;try{await navigator.clipboard.writeText(link);toast('View link copied to clipboard')}catch{toast('View saved in the address bar — copy the URL')}});
