function restoreHash(){if(!location.hash.startsWith('#view='))return;try{let q=JSON.parse(decodeURIComponent(location.hash.slice(6)));if(Number.isFinite(q.theta))orbit.theta=q.theta;if(Number.isFinite(q.phi))orbit.phi=clamp(q.phi,-1.49,1.49);if(Number.isFinite(q.dist))orbit.dist=clamp(q.dist,8,290);if(Array.isArray(q.target)&&q.target.length===3&&q.target.every(Number.isFinite))orbit.target=q.target;if(Number.isFinite(q.y)){maxLevel=clamp(q.y|0,0,H-1);$('height-slider').value=maxLevel;$('height-value').textContent=`Y ${maxLevel} / ${H-1}`}if(typeof q.t==='boolean'){$('terrain').checked=q.t;terrainShown=q.t}if(typeof q.f==='boolean'){$('foliage').checked=q.f;foliageShown=q.f}if(typeof q.e==='boolean'){$('entities').checked=q.e;entitiesShown=q.e}}catch{}}
